    except:
        pass
    return None

def safe_write(port_num, message):
    try:
        subprocess.run(
            f"echo '{message}' > /dev/robot/d{port_num}",
            shell=True,
            timeout=0.5,
            capture_output=True
        )
    except:
        pass

def get_sensors():
    sensors_str = safe_read(2)
    if sensors_str:
        try:
            return [float(x) for x in sensors_str.split(',')]
        except:
            pass
    return []

def get_status():
    status_str = safe_read(3)
    if status_str:
